input.sparql:
SELECT ?point ?times ?zone ?lbl WHERE {
  ?zone brick:hasSubgraph ?sub ;
        rdfs:label "DataCenter_basement_ZN_6" .
  ?point brick:isPointOf ?zone ;
         a brick:AirTemperatureSensor .
  ?point ref:hasTimeseriesId ?times .
}

SELECT ?node ?lbl WHERE {
  ?node a brick:Zone .
  FILTER(str(?node) LIKE "%ZN_6%")
}

SELECT ?cls WHERE {
  ?point a ?cls ; ref:hasTimeseriesId ?t .
  FILTER (?cls != brick:isPointOf)
}

SELECT ?z ?sensor ?ts WHERE {
  ?z a brick:HVAC_Zone .
  ?sensor brick:isPointOf ?z ;
          a brick:Zone_Air_Temperature_Sensor ;
          ref:hasTimeseriesId ?ts .
}

SELECT ?z WHERE {
  ?z a brick:HVAC_Zone .
  FILTER(str(?z) LIKE "%ZN_6%")
}

SELECT ?z WHERE {
  ?z a brick:HVAC_Zone .
  FILTER(str(?z) LIKE "%DataCenter%")
}

SELECT ?z WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdf:type ?t .
  FILTER_REGEX(str(?z), "ZN_6")
}
